  IEnumerable<TControl> Descendants<TControl>(DependencyObject parent) where TControl:DependencyObject{for(int i=0;i<VisualTreeHelper.GetChildrenCount(parent);i++){var child=VisualTreeHelper.GetChild(parent,i);var match=child as TControl;if(match!=null)yield return match;foreach(var item in Descendants<TControl>(child))yield return item;}}
  void ClickTestButton(string name){UpdateLayout();var button=Descendants<Button>(overlay).First(b=>AutomationProperties.GetName(b)==name);if(!button.IsEnabled)throw new Exception("Disabled test button: "+name);button.RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Button.ClickEvent));}
